/* ---------- quotation ---------- */
function Quotation({ plot, onClose, onSave }) {
  const areaSqft = Math.round(plot.area * SQFT);
  const [f, setF] = useState({ name: '', phone: '', rate: 2900, downPct: 20, reg: 0, months: 12 });
  const [saved, setSaved] = useState(false);
  const set = (k) => (e) => setF((s) => ({ ...s, [k]: e.target.value }));

  const total = Math.round(areaSqft * (parseFloat(f.rate) || 0));
  const down = Math.round(total * ((parseFloat(f.downPct) || 0) / 100));
  const reg = parseFloat(f.reg) || 0;
  const balance = total - down - reg;
  const months = Math.max(1, parseInt(f.months, 10) || 1);
  const emi = Math.round(balance / months);
  const inr = (n) => `₹${Math.round(n).toLocaleString('en-IN')}`;

  const save = async () => {
    const ok = await onSave({ plot: plot.name, area: areaSqft, ...f, total, down, balance, emi });
    if (ok) { setSaved(true); setTimeout(() => setSaved(false), 1600); }
  };

  const field = {
    width: '100%', padding: '9px 10px', background: '#0D1117', color: '#EFEAE0',
    border: `1px solid ${HAIR}`, borderRadius: 7, fontFamily: MONO, fontSize: 16,
    outline: 'none', boxSizing: 'border-box',
  };

  return (
    <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(8,11,15,0.78)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16, zIndex: 40 }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: '100%', maxWidth: 520, background: PANEL,
        border: `1px solid ${HAIR}`, borderRadius: 14, padding: 20, maxHeight: '88vh',
        overflowY: 'auto', WebkitOverflowScrolling: 'touch', boxSizing: 'border-box' }}>
        <Eyebrow>Quotation</Eyebrow>
        <div style={{ fontFamily: SANS, fontSize: 24, color: ACCENT, fontWeight: 700,
          letterSpacing: '0.04em', marginBottom: 16 }}>
          PLOT {plot.name} · {areaSqft.toLocaleString('en-IN')} SQ FT
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(190px, 1fr))', gap: 10 }}>
          <div><Eyebrow style={{ marginBottom: 5 }}>Customer</Eyebrow><input style={field} value={f.name} onChange={set('name')} placeholder="Full name" /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Phone</Eyebrow><input style={field} value={f.phone} onChange={set('phone')} inputMode="numeric" placeholder="10 digits" /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Rate / sq ft</Eyebrow><input style={field} type="number" inputMode="decimal" value={f.rate} onChange={set('rate')} /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Down payment %</Eyebrow><input style={field} type="number" inputMode="decimal" value={f.downPct} onChange={set('downPct')} /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Registry &amp; docs</Eyebrow><input style={field} type="number" inputMode="decimal" value={f.reg} onChange={set('reg')} /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Instalments (months)</Eyebrow><input style={field} type="number" inputMode="numeric" value={f.months} onChange={set('months')} /></div>
        </div>

        <div style={{ marginTop: 18, borderTop: `1px solid ${HAIR}` }}>
          {[['Total consideration', inr(total)], ['Down payment', inr(down)],
            ['Registry & documentation', inr(reg)], ['Balance', inr(balance)],
            [`Monthly instalment × ${months}`, inr(emi)]].map(([l, v], i, arr) => (
            <div key={l} style={{ display: 'flex', justifyContent: 'space-between', gap: 12,
              padding: '9px 0', borderBottom: i < arr.length - 1 ? `1px solid ${HAIR}` : 'none',
              fontFamily: MONO, fontSize: i === 0 || i === arr.length - 1 ? 14 : 13,
              color: i === 0 ? ACCENT : i === arr.length - 1 ? '#8CC98F' : '#D5DBE2',
              fontWeight: i === 0 || i === arr.length - 1 ? 700 : 500 }}>
              <span>{l}</span><span>{v}</span>
            </div>
          ))}
        </div>

        <div style={{ display: 'flex', gap: 10, marginTop: 18, flexWrap: 'wrap' }}>
          <button onClick={save} style={{ flex: '1 1 180px', padding: 13, borderRadius: 8, border: 'none',
            background: saved ? '#7CBA81' : ACCENT, color: '#141820', fontFamily: SANS, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase', fontSize: 14, cursor: 'pointer',
            touchAction: 'manipulation' }}>
            {saved ? 'Saved' : 'Save quotation'}
          </button>
          <button onClick={onClose} style={{ flex: '0 1 120px', padding: '13px 20px', borderRadius: 8,
            background: 'transparent', border: `1px solid ${HAIR}`, color: '#B7C0CA', fontFamily: SANS,
            fontSize: 14, letterSpacing: '0.08em', textTransform: 'uppercase', cursor: 'pointer',
            touchAction: 'manipulation' }}>Close</button>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   Persistence — the only part tied to the browser.
   Swap these for your Firestore calls; nothing else changes.
--------------------------------------------------------------- */
const STORE_KEY = 'chicholi:status';
const FIT_KEY = 'chicholi:fit';

async function loadStatus() {
  try {
    const raw = window.localStorage.getItem(STORE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) { return {}; }
}
async function saveStatus(map) {
  try { window.localStorage.setItem(STORE_KEY, JSON.stringify(map)); return true; }
  catch (e) { return false; }
}
async function saveQuotation(record) {
  try {
    window.localStorage.setItem(`chicholi:quote:${record.plot}:${Date.now()}`, JSON.stringify(record));
    return true;
  } catch (e) { return false; }
}

/** the placement survives a reload, so you never lose an alignment
    just because you refreshed before hitting Copy fit */
function loadFit() {
  try {
    const raw = window.localStorage.getItem(FIT_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}
function persistFit(mode, n) {
  try { window.localStorage.setItem(FIT_KEY, JSON.stringify({ mode, ...n })); } catch (e) { /* ignore */ }
}

/* ---------- app ---------- */
export default function ChicholiMasterPlan() {
  const mapRef = useRef(null);
  const [selected, setSelected] = useState(null);
  const [quote, setQuote] = useState(null);
  const [status, setStatusMap] = useState({});
  const [loaded, setLoaded] = useState(false);
  const [search, setSearch] = useState('');
  const [minA, setMinA] = useState('');
  const [maxA, setMaxA] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [showNumbers, setShowNumbers] = useState(true);
  const [planOpacity, setPlanOpacity] = useState(1);

  const saved = typeof window !== 'undefined' ? loadFit() : null;
  const [fitMode, setFitMode] = useState(saved ? saved.mode : FIT);
  const [nudge, setNudge] = useState(saved
    ? { rot: saved.rot, scale: saved.scale, east: saved.east, north: saved.north }
    : NUDGE);
  const [adjust, setAdjust] = useState(false);
  const [alignStep, setAlignStep] = useState(0);
  const picks = useRef([]);

  useEffect(() => { persistFit(fitMode, nudge); }, [fitMode, nudge]);

  /* the map must fill the device, not a fixed 100vh that mobile browser
     chrome then eats into */
  useEffect(() => {
    let meta = document.querySelector('meta[name="viewport"]');
    if (!meta) {
      meta = document.createElement('meta');
      meta.setAttribute('name', 'viewport');
      document.head.appendChild(meta);
    }
    meta.setAttribute('content',
      'width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover');
  }, []);

  useEffect(() => {
    let alive = true;
    loadStatus().then((m) => { if (alive) { setStatusMap(m); setLoaded(true); } });
    return () => { alive = false; };
  }, []);

  const setStatus = useCallback((num, st) => {
    setStatusMap((m) => {
      const next = { ...m, [num]: st };
      if (st === 'available') delete next[num];
      saveStatus(next);
      return next;
    });
  }, []);

  const matches = useMemo(() => {
    const q = search.trim();
    const lo = parseFloat(minA), hi = parseFloat(maxA);
    if (!q && isNaN(lo) && isNaN(hi) && statusFilter === 'all') return null;
    const s = new Set();
    PLOTS.forEach((p) => {
      if (q && !p.name.includes(q)) return;
      if (!isNaN(lo) && p.area < lo) return;
      if (!isNaN(hi) && p.area > hi) return;
      if (statusFilter !== 'all' && (status[p.name] || 'available') !== statusFilter) return;
      s.add(p.name);
    });
    return s;
  }, [search, minA, maxA, statusFilter, status]);

  const selPlot = selected ? BY_NAME.get(selected) : null;

  /* the plan's own transform, mirrored here so the app can convert a
     plot to lat/lng for the panel and for export */
  const base = useMemo(() => buildBase(fitMode), [fitMode]);
  const centreEN = useMemo(() => base.fwd(META.w / 2, -META.h / 2), [base]);
  const planToLL = useCallback((x, y) => {
    const p = base.fwd(x, -y);
    const c = Math.cos(nudge.rot * D2R) * nudge.scale;
    const s = Math.sin(nudge.rot * D2R) * nudge.scale;
    const dx = p[0] - centreEN[0], dy = p[1] - centreEN[1];
    return FRAME.toLL(centreEN[0] + c * dx - s * dy + nudge.east,
                      centreEN[1] + s * dx + c * dy + nudge.north);
  }, [base, centreEN, nudge]);

  const selLL = selPlot ? planToLL(selPlot.c[0], selPlot.c[1]) : null;

  /* how far the current placement misses your control points. Under a
     rigid fit this also tells you whether the two readings are even
     consistent with the drawing's true size. */
  const residual = useMemo(() => {
    if (!GCP.length) return null;
    const d = GCP.map((g) => {
      const ll = planToLL(g.plan[0], g.plan[1]);
      const a = FRAME.toEN(ll.lat, ll.lng), b = FRAME.toEN(g.lat, g.lng);
      return Math.hypot(a[0] - b[0], a[1] - b[1]);
    });
    return d.reduce((s, v) => s + v, 0) / d.length;
  }, [planToLL]);

  const fitWholePlan = useCallback(() => {
    const map = mapRef.current;
    if (!map || !window.google) return;
    const b = new window.google.maps.LatLngBounds();
    [[0, 0], [META.w, 0], [0, META.h], [META.w, META.h]]
      .forEach((p) => b.extend(planToLL(p[0], p[1])));
    GCP.forEach((g) => b.extend({ lat: g.lat, lng: g.lng }));
    map.fitBounds(b, 48);
  }, [planToLL]);

  /** frame a plot into the part of the map the panel does not cover */
  const zoomTo = useCallback((plot) => {
    const map = mapRef.current;
    if (!map || !window.google) return;
    const b = new window.google.maps.LatLngBounds();
    plot.pts.forEach((p) => b.extend(planToLL(p[0], p[1])));
    /* Fill the view with the plot. The tilt compresses it vertically and
       the turn swings its corners out, so leave room for both, plus the
       dimension figures that sit outside the boundary. */
    const phone = window.innerWidth <= 640;
    map.fitBounds(b, phone
      ? { top: 90, bottom: Math.round(window.innerHeight * 0.44), left: 60, right: 60 }
      : { top: 130, bottom: 130, left: 110, right: 350 });
  }, [planToLL]);

  const onSelect = useCallback((name) => {
    setSelected((cur) => {
      const next = name === cur ? null : name;
      if (next) zoomTo(BY_NAME.get(next));
      return next;
    });
  }, [zoomTo]);

  /* two matched landmarks pin down turn, size and position exactly —
     far more reliable than four corner readings that disagree */
  const onAlignClick = useCallback((lat, lng, enToPlan) => {
    const en = FRAME.toEN(lat, lng);
    setAlignStep((step) => {
      if (step % 2 === 1) {
        picks.current.push({ plan: enToPlan(en[0], en[1]) });
      } else {
        picks.current[picks.current.length - 1].ground = en;
      }
      if (step === 4) {
        const [a, b] = picks.current;
        const src = [toPlan(a.plan[0], a.plan[1]), toPlan(b.plan[0], b.plan[1])];
        if (Math.hypot(src[1][0] - src[0][0], src[1][1] - src[0][1]) < 20) {
          picks.current = [];
          return 1;   // too close together to fix an angle, start over
        }
        const t = fitSimilarity(src, [a.ground, b.ground], fitMode === 'rigid');
        const cur = buildBase(fitMode);
        const c0 = cur.fwd(META.w / 2, -META.h / 2);
        const want = t.fwd(META.w / 2, -META.h / 2);
        setNudge({
          rot: (t.th - (cur.th || 0)) / D2R,
          scale: t.s / (cur.s || 1),
          east: want[0] - c0[0],
          north: want[1] - c0[1],
        });
        picks.current = [];
        return 0;
      }
      return step + 1;
    });
  }, [fitMode]);

  const copyFit = useCallback(() => {
    const txt =
`const FIT = '${fitMode}';
const NUDGE = { rot: ${nudge.rot.toFixed(4)}, scale: ${nudge.scale.toFixed(6)}, ` +
`east: ${nudge.east.toFixed(3)}, north: ${nudge.north.toFixed(3)} };`;
    if (navigator.clipboard) navigator.clipboard.writeText(txt).catch(() => {});
    // eslint-disable-next-line no-console
    console.log(txt);
  }, [fitMode, nudge]);

  const shown = matches ? matches.size : PLOTS.length;

  const inputStyle = {
    padding: '7px 10px', background: '#0D1117', color: '#EFEAE0',
    border: `1px solid ${HAIR}`, borderRadius: 7, fontFamily: MONO, fontSize: 16,
    outline: 'none', boxSizing: 'border-box', minWidth: 0,
  };

  return (
    <div style={{ width: '100%', height: '100dvh', minHeight: '100vh', position: 'relative',
      display: 'flex', flexDirection: 'column', background: CANVAS, color: '#E7E1D5',
      fontFamily: BODY, overflow: 'hidden' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=Poppins:wght@400;500;600;700&display=swap');
        * { -webkit-tap-highlight-color: transparent; }
        input::placeholder { color: #5F6B78; }
        *:focus-visible { outline: 2px solid ${ACCENT}; outline-offset: 2px; }
        .toolbar { display: flex; align-items: center; gap: 8px; padding: 9px 14px;
          border-bottom: 1px solid ${HAIR}; flex-wrap: wrap; }
        .toolbar .spacer { margin-left: auto; }
        .toolbar-count { font-family: ${MONO}; font-size: 12px; color: ${MUTED}; }
        .gm-style img { max-width: none; }
        @media (max-width: 640px) {
          .toolbar { gap: 6px; padding: 8px 10px; overflow-x: auto; flex-wrap: nowrap;
            -webkit-overflow-scrolling: touch; }
          .toolbar > * { flex: 0 0 auto; }
          .toolbar .spacer { margin-left: 6px; }
          .toolbar .area-label { display: none; }
        }
      `}</style>

      <div className="toolbar">
        <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Plot no."
          inputMode="numeric" style={{ ...inputStyle, width: 92 }} />
        <span className="area-label" style={{ color: MUTED, fontSize: 12, fontFamily: SANS,
          letterSpacing: '0.12em', textTransform: 'uppercase' }}>Area m²</span>
        <input value={minA} onChange={(e) => setMinA(e.target.value)} type="number" inputMode="decimal"
          placeholder={`${Math.floor(AREA_MIN)}`} style={{ ...inputStyle, width: 76 }} />
        <input value={maxA} onChange={(e) => setMaxA(e.target.value)} type="number" inputMode="decimal"
          placeholder={`${Math.ceil(AREA_MAX)}`} style={{ ...inputStyle, width: 76 }} />

        <Chip active={statusFilter === 'all'} onClick={() => setStatusFilter('all')}>All</Chip>
        {Object.entries(STATUS).map(([k, s]) => (
          <Chip key={k} active={statusFilter === k} swatch={s.dot}
            onClick={() => setStatusFilter(k)}>{s.label}</Chip>
        ))}

        <span className="spacer" />
        <span className="toolbar-count">{shown} / {PLOTS.length}</span>
        <Chip active={showNumbers} onClick={() => setShowNumbers((v) => !v)}>Numbers</Chip>
        <Chip active={adjust} onClick={() => setAdjust((v) => !v)}>Adjust</Chip>
        <Chip onClick={() => { setSearch(''); setMinA(''); setMaxA(''); setStatusFilter('all'); }}>Clear</Chip>
        <Chip onClick={() => { setSelected(null); fitWholePlan(); }}>Fit plan</Chip>
      </div>

      <div style={{ flex: 1, position: 'relative', minHeight: 0 }}>
        <PlanMap
          mapRef={mapRef}
          selected={selected} onSelect={onSelect}
          matches={matches} status={status} showNumbers={showNumbers}
          planOpacity={planOpacity}
          fitMode={fitMode} nudge={nudge} setNudge={setNudge} adjust={adjust}
          alignStep={alignStep} onAlignClick={onAlignClick}
          onReady={fitWholePlan}
        />

        {adjust && (
          <AdjustBar
            nudge={nudge} setNudge={setNudge}
            fitMode={fitMode} setFitMode={setFitMode}
            planOpacity={planOpacity} setPlanOpacity={setPlanOpacity}
            alignStep={alignStep} residual={residual}
            onAlign={() => { picks.current = []; setAlignStep((s) => (s ? 0 : 1)); }}
            onCopy={copyFit}
          />
        )}

        <DetailPanel
          plot={selPlot} status={status} setStatus={setStatus} latLng={selLL}
          onClose={() => setSelected(null)}
          onQuote={() => setQuote(selPlot)}
        />
      </div>

      {quote && <Quotation plot={quote} onClose={() => setQuote(null)} onSave={saveQuotation} />}

      {!loaded && (
        <div style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center',
          background: CANVAS, color: MUTED, fontFamily: MONO, fontSize: 13, zIndex: 50 }}>
          Loading layout…
        </div>
      )}
    </div>
  );
}